package reading_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"french-learning-app/internal/domain"
)

// The reading/listening workbook (content/workbooks) publishes its reading
// passages in the authored-pack format and as learner-lesson bodies. These
// files are generated by tools/workbooks; this test keeps them inside the
// server's own contracts. The pack file is not embedded by the server.
func TestWorkbookReadingPackAdapterValidates(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "content", "workbooks", "adapters", "reading_pack_workbook_rl_v1.json"))
	if err != nil {
		t.Fatalf("read adapter: %v", err)
	}
	pack, err := domain.ParseReadingPack(raw)
	if err != nil {
		t.Fatalf("ParseReadingPack: %v", err)
	}
	if len(pack.Passages) != 12 {
		t.Fatalf("passages = %d, want 12", len(pack.Passages))
	}

	var lessons struct {
		Bodies []struct {
			Unit string `json:"workbook_unit"`
			Body struct {
				Title     string `json:"title"`
				Text      string `json:"text"`
				SourceURL string `json:"source_url"`
			} `json:"body"`
		} `json:"bodies"`
	}
	raw, err = os.ReadFile(filepath.Join("..", "..", "content", "workbooks", "adapters", "reading_learner_lessons_rl_v1.json"))
	if err != nil {
		t.Fatalf("read lessons: %v", err)
	}
	if err := json.Unmarshal(raw, &lessons); err != nil {
		t.Fatalf("decode lessons: %v", err)
	}
	if len(lessons.Bodies) != len(pack.Passages) {
		t.Fatalf("lesson bodies = %d, want %d", len(lessons.Bodies), len(pack.Passages))
	}
	for i, b := range lessons.Bodies {
		p := pack.Passages[i]
		if _, err := domain.NormalizeListeningTitle(b.Body.Title); err != nil {
			t.Errorf("%s title: %v", b.Unit, err)
		}
		if b.Body.SourceURL != "" {
			t.Errorf("%s: a workbook lesson has no source link", b.Unit)
		}
		segs, err := domain.ParseReadingText(b.Body.Text)
		if err != nil {
			t.Fatalf("%s ParseReadingText: %v", b.Unit, err)
		}
		if len(segs) != len(p.Segments) {
			t.Fatalf("%s: %d paragraphs as a lesson, %d in the pack", b.Unit, len(segs), len(p.Segments))
		}
		for k := range segs {
			if segs[k] != p.Segments[k] {
				t.Errorf("%s: paragraph %s differs between lesson and pack", b.Unit, segs[k].ID)
			}
		}
	}
}

// The productive workbook publishes writing tasks for POST /writing/tasks and
// a prompt set in the authored writing format; both must pass the server's
// own validation, and the samples must fit their word ranges as the server
// counts words.
func TestWorkbookWritingAdaptersValidate(t *testing.T) {
	dir := filepath.Join("..", "..", "content", "workbooks")
	raw, err := os.ReadFile(filepath.Join(dir, "adapters", "writing_prompts_workbook_pw_v1.json"))
	if err != nil {
		t.Fatalf("read prompt set: %v", err)
	}
	set, err := domain.ParseWritingPrompts(raw)
	if err != nil {
		t.Fatalf("ParseWritingPrompts: %v", err)
	}
	if len(set.Prompts) != 12 {
		t.Fatalf("prompts = %d, want 12", len(set.Prompts))
	}

	raw, err = os.ReadFile(filepath.Join(dir, "adapters", "writing_tasks_pw_v1.json"))
	if err != nil {
		t.Fatalf("read task bodies: %v", err)
	}
	var wire struct {
		Bodies []struct {
			Unit string `json:"workbook_unit"`
			Body struct {
				Title        string   `json:"title"`
				Prompt       string   `json:"prompt"`
				Requirements []string `json:"requirements"`
				WordMin      int      `json:"word_min"`
				WordMax      int      `json:"word_max"`
			} `json:"body"`
		} `json:"bodies"`
	}
	if err := json.Unmarshal(raw, &wire); err != nil {
		t.Fatalf("decode task bodies: %v", err)
	}
	if len(wire.Bodies) != 12 {
		t.Fatalf("task bodies = %d, want 12", len(wire.Bodies))
	}
	for _, b := range wire.Bodies {
		if _, err := domain.NormalizeWritingTask(domain.WritingTask{Title: b.Body.Title, Prompt: b.Body.Prompt,
			Requirements: b.Body.Requirements, WordMin: b.Body.WordMin, WordMax: b.Body.WordMax}); err != nil {
			t.Errorf("%s: %v", b.Unit, err)
		}
	}

	var doc struct {
		Units []struct {
			ID      string `json:"id"`
			Writing struct {
				WordMin int `json:"word_min"`
				WordMax int `json:"word_max"`
			} `json:"writing"`
			Sample struct {
				Text string `json:"text"`
			} `json:"writing_sample"`
			Retry struct {
				Draft     string `json:"draft"`
				Corrected string `json:"corrected"`
			} `json:"retry"`
		} `json:"units"`
	}
	raw, err = os.ReadFile(filepath.Join(dir, "productive_v1.json"))
	if err != nil {
		t.Fatalf("read workbook: %v", err)
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("decode workbook: %v", err)
	}
	for _, u := range doc.Units {
		n := domain.CountWritingWords(u.Sample.Text)
		if n < u.Writing.WordMin || n > u.Writing.WordMax {
			t.Errorf("%s: sample has %d words, outside %d-%d", u.ID, n, u.Writing.WordMin, u.Writing.WordMax)
		}
		for _, text := range []string{u.Sample.Text, u.Retry.Draft, u.Retry.Corrected} {
			if _, _, err := domain.NormalizeWritingDraft(text); err != nil {
				t.Errorf("%s: %v", u.ID, err)
			}
		}
		if u.Retry.Draft == u.Retry.Corrected {
			t.Errorf("%s: corrected draft equals the draft", u.ID)
		}
	}
}

// The productive workbook also publishes its speaking tasks in the Speaking
// section's prompt format. The server does not embed this file; the test keeps
// it inside the server's own parser.
func TestWorkbookSpeakingAdapterValidates(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "content", "workbooks", "adapters", "speaking_prompts_workbook_pw_v1.json"))
	if err != nil {
		t.Fatalf("read speaking prompt set: %v", err)
	}
	set, err := domain.ParseSpeakingPrompts(raw)
	if err != nil {
		t.Fatalf("ParseSpeakingPrompts: %v", err)
	}
	if len(set.Prompts) != 12 {
		t.Fatalf("prompts = %d, want 12", len(set.Prompts))
	}
}
